//! vnc-050 ADR-005 nullable-`fp` parity rows (Rust side). The accepting
//! `fp: null` golden row lives in `bundle-golden.json` (generated by
//! `bundle_codec.rs`); these pin the reject set the JS decoder must mirror:
//! `""`, `"sha256:"`, uppercase hex, non-string/non-null, missing key.

use base64::Engine;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;

use unimatrix_server::client_bundle::{BUNDLE_SCHEME, BundleError, decode_bundle, encode_bundle};

const TEST_TOKEN: &str = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
const TEST_MCP_URL: &str = "https://cloud.example:8443/v1/alpha";
const TEST_OBSERVE_URL: &str = "https://cloud.example:8443/v1/alpha/observe";

fn encode_json(json: &str) -> String {
    format!("{BUNDLE_SCHEME}{}", URL_SAFE_NO_PAD.encode(json.as_bytes()))
}

fn fp_payload(fp_json: &str) -> String {
    encode_json(&format!(
        "{{\"v\":2,\"mcp_url\":\"{TEST_MCP_URL}\",\"observe_url\":\"{TEST_OBSERVE_URL}\",\"token\":\"{TEST_TOKEN}\",\"fp\":{fp_json}}}"
    ))
}

#[test]
fn test_fp_null_accepted_and_round_trips() {
    let decoded = decode_bundle(&fp_payload("null")).expect("fp:null must decode");
    assert_eq!(decoded.fp, None);
    let wire = encode_bundle(2, TEST_MCP_URL, TEST_OBSERVE_URL, TEST_TOKEN, None).unwrap();
    assert_eq!(
        wire,
        fp_payload("null"),
        "encoder emits fp:null with key present"
    );
}

#[test]
fn test_fp_invalid_shapes_rejected() {
    let upper = format!("\"sha256:{}\"", "A".repeat(64));
    for bad in [
        "\"\"",
        "\"sha256:\"",
        upper.as_str(),
        "0",
        "false",
        "[]",
        "{}",
    ] {
        assert!(
            matches!(decode_bundle(&fp_payload(bad)), Err(BundleError::Schema(_))),
            "fp {bad} must reject"
        );
    }
    // Missing fp key (4 keys) still rejects even though null is allowed.
    let missing = encode_json(&format!(
        "{{\"v\":2,\"mcp_url\":\"{TEST_MCP_URL}\",\"observe_url\":\"{TEST_OBSERVE_URL}\",\"token\":\"{TEST_TOKEN}\"}}"
    ));
    assert!(matches!(
        decode_bundle(&missing),
        Err(BundleError::Schema(_))
    ));
}
